package com.insight.quantlife.tests;
import android.app.*;import android.os.*;import org.json.*;import java.io.*;import com.insight.quantlife.*;
/** Synthetic-only signed upgrade, real SQLite/WebView, mocked LLM chunk reading. */
public class WorkCalendarWikiTest extends WorkClockTest {
 void seedNew()throws Exception{holdAutomation();check(getTargetContext().getPackageManager().getPackageInfo(getTargetContext().getPackageName(),0).versionName.equals("1.7.5"),"Previous signed 1.7.5");JSONObject snap=init();try(TrackStore t=new TrackStore(getTargetContext())){snap.put("gpx",t.gpx("2026-12-15")).put("raw",t.diagnostics("2026-12-15").getJSONArray("rawPoints"));}try(FileOutputStream f=getTargetContext().openFileOutput("calendar-wiki-baseline.json",0)){f.write(snap.toString().getBytes("UTF-8"));}}
 void upgrade()throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=getTargetContext().openFileInput("calendar-wiki-baseline.json")){byte[] b=new byte[8192];int n;while((n=in.read(b))>0)out.write(b,0,n);}JSONObject old=new JSONObject(out.toString("UTF-8")),cur=init();check(getTargetContext().getPackageManager().getPackageInfo(getTargetContext().getPackageName(),0).versionName.equals("1.7.6"),"Signed cover install 1.7.6");for(String k:new String[]{"records","messages","wikiPages","chatSession"})check(old.get(k).toString().equals(cur.get(k).toString()),"Upgrade preserves "+k);JSONObject a=old.getJSONObject("settings"),b=cur.getJSONObject("settings");a.remove("wikiAutomation");b.remove("wikiAutomation");check(a.toString().equals(b.toString()),"Model/search configuration preserved");try(TrackStore t=new TrackStore(getTargetContext())){check(old.getString("gpx").equals(t.gpx("2026-12-15"))&&old.getJSONArray("raw").toString().equals(t.diagnostics("2026-12-15").getJSONArray("rawPoints").toString()),"Raw GPS and D route preserved");}}
 void calendar()throws Exception{
  holdAutomation();JSONArray old=init().getJSONArray("records");for(int i=0;i<old.length();i++)if(old.getJSONObject(i).getString("id").startsWith("calendar-")||old.getJSONObject(i).optString("title").equals("长文回归"))h.call("deleteRecord",new JSONObject().put("id",old.getJSONObject(i).getString("id")));
  for(int i=1;i<=31;i++){String date=String.format(java.util.Locale.US,"2024-10-%02d",i);JSONObject r=new JSONObject().put("id","calendar-shift-"+i).put("type","work").put("date",date).put("title","合成班次 "+i).put("note","").put("tags",new JSONArray()).put("durationMinutes",480).put("workStart",date+"T09:00:00").put("workEnd",date+"T18:00:00").put("breaks",new JSONArray().put(new JSONObject().put("start",date+"T12:00:00").put("end",date+"T13:00:00")));h.call("saveRecord",new JSONObject().put("record",r).put("allowDuplicate",true));}
  for(int i=0;i<7;i++)h.call("saveRecord",new JSONObject().put("record",note("calendar-log-"+i,"合成当天进展 "+i).put("date","2024-10-15").put("title","当天日志 "+i)).put("allowDuplicate",true));h.call("saveRecord",new JSONObject().put("record",note("calendar-search","cal-unique-evidence").put("date","2024-09-01")));reload();holdAutomation();click("[data-page=records]");click("[data-record-tab=work]");click("[data-range=month]");h.js("document.querySelector('#work-day-input').value='2024-10-15';document.querySelector('#work-day-input').dispatchEvent(new Event('change'))");
  jsCheck("document.querySelectorAll('[data-work-day]').length===31","Month calendar shows every day");jsCheck("document.querySelector('.work-overview').innerText.includes('248')","Monthly net sum 31 times eight hours is exact");jsCheck("document.querySelector('[data-work-view=logs]').getAttribute('aria-selected')==='true'&&document.querySelectorAll('.work-day-list [data-record]').length===5&&!document.querySelector('.work-day-list [data-record^=calendar-shift]')","Logs default with five per page, not 31 shifts before journals");jsCheck("document.querySelector('[data-work-day=\\\"2024-10-15\\\"] .has-logs')!==null","Calendar marks days containing journals");click("#work-month-calendar summary");Thread.sleep(500);h.screenshot("work-calendar-month-1.7.6.png");click("#work-month-calendar summary");Thread.sleep(300);h.screenshot("work-calendar-logs-1.7.6.png");
  click("[data-work-page='1']");jsCheck("document.querySelectorAll('.work-day-list [data-record]').length===2","Next page shows remaining logs");click("[data-work-view=hours]");jsCheck("document.querySelectorAll('.work-day-list [data-record]').length===1&&document.querySelector('.work-day-list').innerText.includes('8小时')","Hours tab shows only selected day, net rest deducted once");click("[data-work-view=logs]");click("[data-work-day='2024-10-16']");jsCheck("!document.querySelector('.work-day-list [data-record]')","Date selection does not mix other-day journals");click("#work-month-calendar summary");click("[data-work-month='1']");jsCheck("document.querySelectorAll('[data-work-day]').length===30&&document.querySelector('#work-day-input').value==='2024-11-01'","Next month changes calendar and selected date coherently");click("[data-work-month='-1']");click("[data-work-day='2024-10-15']");h.js("document.querySelector('#work-note-search').value='cal-unique-evidence';document.querySelector('#work-note-search').dispatchEvent(new Event('input'))");jsCheck("document.querySelectorAll('.work-day-list [data-record]').length===1&&document.querySelector('.work-day-list').innerText.includes('2024-09-01')","Journal search finds all-history match outside selected day");
  h.js("document.querySelector('#work-note-search').value='';document.querySelector('#work-note-search').dispatchEvent(new Event('input'))");click("[data-action=add-work-note]");jsCheck("document.querySelector('#work-note-date').value==='2024-10-15'&&!document.querySelector('#work-note-content').hasAttribute('maxlength')","New log uses selected date and has no fixed note length cap");h.js("document.querySelector('#work-note-content').value='知识'.repeat(80000)+'ONLY_TAIL_EVIDENCE';document.querySelector('#work-note-title').value='长文回归';document.querySelector('#work-note-tags').value='长文回归主题';document.querySelector('#work-note-form').requestSubmit()");until("!document.querySelector('#editor').open");JSONArray all=init().getJSONArray("records");JSONObject longRecord=null;for(int i=0;i<all.length();i++)if(all.getJSONObject(i).optString("title").equals("长文回归"))longRecord=all.getJSONObject(i);check(longRecord!=null&&longRecord.getString("note").length()>160000&&longRecord.getString("note").endsWith("ONLY_TAIL_EVIDENCE"),"Native SQLite preserves >160k manual note including final evidence");h.js("window.__longId="+JSONObject.quote(longRecord.getString("id")));jsCheck("document.documentElement.scrollWidth<=innerWidth+1","Calendar and journal UI fit phone width");
 }
 void wikiMock()throws Exception{h.js("window.__wikiRead=0;window.__wikiTail=false;window.__wikiReads=[];window.__reply=window.nativeReply;window.__testPending=new Map();window.__testId=0;window.nativeReply=function(r){const p=__testPending.get(r.id);if(p){__testPending.delete(r.id);r.error?p.reject(Error(r.error)):p.resolve(r.data)}else __reply(r)};window.__realNative=LifeNative;LifeNative={call:function(action,payload,rid){if(action!=='ask'){__realNative.call(action,payload,rid);return;}const p=JSON.parse(payload),d=JSON.parse(p.messages.at(-1).content);let raw;if(p.tool.name==='plan_wiki_topics'){raw={items:d.records.map(r=>({recordId:r.id,topics:['完整长文']}))};}else{if(d.records){__wikiRead+=d.records.reduce((n,r)=>n+r.note.length,0);__wikiReads.push(...d.records);if(d.records.some(r=>r.note.includes('ONLY_TAIL_EVIDENCE'))) __wikiTail=true;}const tail=d.records?d.records.some(r=>r.note.includes('ONLY_TAIL_EVIDENCE')):d.partialPages.some(p=>p.summary.includes('ONLY_TAIL_EVIDENCE'));raw={summary:tail?'已核对 ONLY_TAIL_EVIDENCE':'已阅读当前片段',aliases:[],concepts:[],sourceIds:d.sourceIds||d.records.map(r=>r.id)};}setTimeout(()=>nativeReply({id:rid,data:{text:JSON.stringify(raw),model:'synthetic-full-note'}}),10)}};window.__testApi=(a,p={})=>new Promise((resolve,reject)=>{const id='wiki-test-'+(++__testId);__testPending.set(id,{resolve,reject});LifeNative.call(a,JSON.stringify(p),id)})");}
 void runCompile(int budget)throws Exception{h.js("window.__wikiDone=false;window.__wikiError='';window.__wikiPage=null;(async()=>{try{const rs=await __testApi('getRecords');const r=rs.find(r=>r.title==='长文回归');__longId=r.id;__wikiPage=await WikiCompiler.compile({records:[r],topic:'长文回归主题',api:__testApi,ask:p=>__testApi('ask',p),budget:"+budget+"});if(__wikiPage)await __testApi('saveWiki',{page:__wikiPage});}catch(e){__wikiError=e.message;}finally{__wikiDone=true}})()");until("__wikiDone");jsCheck("__wikiError===''","Wiki native bridge request succeeds: "+h.js("__wikiError"));}
 void wiki()throws Exception{
  holdAutomation();wikiMock();runCompile(1);jsCheck("__wikiPage===null&&!__wikiTail","First batch remains pending instead of claiming full read");JSONObject job=(JSONObject)h.call("getWikiJob",new JSONObject().put("id","compile-长文回归主题"));check(job.getInt("next")==1,"Chunk progress persisted in actual SQLite");int first=Integer.parseInt(h.js("__wikiRead"));reload();holdAutomation();wikiMock();runCompile(99999);JSONObject page=null;JSONArray pages=init().getJSONArray("wikiPages");for(int i=0;i<pages.length();i++)if(pages.getJSONObject(i).optString("topic").equals("长文回归主题"))page=pages.getJSONObject(i);check(page!=null&&page.getString("summary").contains("ONLY_TAIL_EVIDENCE")&&!page.getBoolean("partial")&&!page.getBoolean("notesTruncated"),"Resumed Wiki stores tail evidence, complete coverage and no truncation");String rid=new JSONArray(h.js("[__longId]")).getString(0);check(first+Integer.parseInt(h.js("__wikiRead"))==find(rid).getString("note").length(),"Every original character read once across restart, not just prefix");check(page.getJSONArray("sourceIds").length()==1&&page.getJSONArray("sourceIds").getString(0).equals(rid),"All chunks retain one real source reference");
  JSONObject changed=find(rid);changed.put("note",changed.getString("note")+"\n合成修订");h.call("saveRecord",new JSONObject().put("record",changed));boolean rejected=false;try{h.call("saveWikiJob",new JSONObject().put("job",job));}catch(Exception ex){rejected=true;}check(rejected,"Concurrent source edit rejects old checkpoint version");reload();holdAutomation();jsCheck("LifeWiki.isStale((()=>null)()||{compilerVersion:1},[])","Legacy truncated Wiki is considered stale for full rebuild");
 }
 void automatic()throws Exception{holdAutomation();while(queue().getInt("count")>0)h.call("ackWikiQueue",new JSONObject().put("jobs",queue().getJSONArray("jobs")));StringBuilder text=new StringBuilder();for(int i=0;i<55000;i++)text.append("自");text.append("ONLY_TAIL_EVIDENCE").append("\nsynthetic-run-").append(System.nanoTime());h.call("saveRecord",new JSONObject().put("record",note("calendar-auto-long",text.toString()).put("title","自动长文回归").put("date","2024-10-15")).put("allowDuplicate",true));h.call("saveSettings",new JSONObject().put("settings",new JSONObject().put("profile",model("SYNTHETIC-ONLY"))));reload();holdAutomation();wikiMock();h.js("Object.defineProperty(document,\'hidden\',{configurable:true,get:()=>false});AutoWiki.resume()");JSONObject job=null;for(int i=0;i<80;i++){Object j=h.call("getWikiJob",new JSONObject().put("id","classify-calendar-auto-long"));if(j instanceof JSONObject&&((JSONObject)j).optInt("next")==2){job=(JSONObject)j;break;}Thread.sleep(100);}check(job!=null&&queue().getInt("count")==1,"Automatic classification checkpoints after two chunks and does not acknowledge unread tail");for(int i=0;i<450&&queue().getInt("count")>0;i++)Thread.sleep(100);check(queue().getInt("count")==0,"Automatic idle batches finish and acknowledge complete source");JSONObject source=find("calendar-auto-long");check(source.getJSONArray("wikiTopics").getString(0).equals("完整长文"),"Automatic topic assignment persisted after reading all chunks");JSONObject page=null;JSONArray pages=init().getJSONArray("wikiPages");for(int i=0;i<pages.length();i++)if(pages.getJSONObject(i).optString("topic").equals("完整长文"))page=pages.getJSONObject(i);check(page!=null&&page.getString("summary").contains("ONLY_TAIL_EVIDENCE")&&!page.getBoolean("partial"),"Automatic compiler retains final evidence and complete coverage");int read=Integer.parseInt(h.js("__wikiReads.filter(r=>r.id==='calendar-auto-long').reduce((n,r)=>n+r.note.length,0)"));check(read==text.length(),"Automatic summarizer reads all source characters without repeated prefixes; actual="+read+", expected="+text.length());jsCheck("(()=>{const chunks=__wikiReads.filter(r=>r.id==='calendar-auto-long').sort((a,b)=>a.noteStart-b.noteStart);let end=0;for(const c of chunks){if(c.noteStart!==end)return false;end=c.noteEnd;}return end==="+text.length()+"})()","Automatic source chunks have contiguous offsets with no overlap");holdAutomation();}
 @Override public void onStart(){Bundle r=new Bundle();try{h=new MainHost(this);h.open();if(phase.equals("seed"))seedNew();else if(phase.equals("auto"))automatic();else{holdAutomation();if(phase.equals("flow"))upgrade();if(!phase.equals("wiki"))calendar();wiki();}r.putString("stream","PASS "+passed+" calendar/full-note/native/upgrade checks; mock model only\n");finish(Activity.RESULT_OK,r);}catch(Throwable e){r.putString("stream","FAIL after "+passed+": "+e+"\n");finish(Activity.RESULT_CANCELED,r);}}
}
